# 103-105: балансы продукта А (формулы с числами под членами)
def _bal(terms, vals):
    top = ''.join('<td>%s</td>' % t for t in terms)
    bot = ''.join('<td style="text-align:center;font-size:.9em">%s</td>' % v for v in vals)
    return '<table class="eqt" style="margin:0 auto;border-collapse:collapse"><tr style="vertical-align:top">%s</tr><tr>%s</tr></table>' % (top, bot)


